import {ELEMENTS,SUBSTANCES,countCards,keyOf,formulaOf,formatFormula,massOf,massText,graphMatches} from './chemistry.mjs';
import {newGame,legalMoves,selectedMoves,play,skip,chooseBotMove,shuffle,auditGame} from './engine.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const names=['你','林同学','周同学'];const modal=$('#modal');let state,selected=new Set(),sort='element',panel='suggestions',query='',timer=null,toastTimer,botEpoch=0,hintIndex=0,puzzle=null;
try{const saved=JSON.parse(localStorage.getItem('chemcards-game-v1'));if(saved?.version===1&&[72,108].includes(saved.size)&&saved.hands?.length===3&&saved.deck.every(e=>ELEMENTS[e])&&auditGame(saved))state=saved;}catch{}
if(!state)state=newGame({seed:crypto.getRandomValues(new Uint32Array(1))[0]});
try{sort=localStorage.getItem('chemcards-sort')||'element';}catch{}$('#sort').value=sort;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=s=>formatFormula(esc(s));
const selectedCards=()=>[...selected].map(i=>state.hands[0][i]).filter(Boolean);
function save(){try{localStorage.setItem('chemcards-game-v1',JSON.stringify(state));localStorage.setItem('chemcards-sort',sort);}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function render(){
 $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));});
 $('#mode-title').innerHTML=state.mode==='A'?'质量竞技<span> / 01</span>':'化学接龙<span> / 02</span>';
 $('#deck-info').textContent=`${state.size} 张 · ${state.strategy==='mixed'?'配方混合':'自由随机'}牌库`;
 $('#opponents').innerHTML=[1,2].map(p=>`<div class="opponent ${state.current===p&&state.winner===null?'active':''}"><span class="avatar">${p===1?'林':'周'}</span><div><strong>${names[p]}</strong><small>${state.current===p&&state.winner===null?'正在思考 · ':''}${state.hands[p].length} 张手牌</small></div><div class="mini-backs" aria-hidden="true">${'<i></i>'.repeat(Math.min(5,state.hands[p].length))}</div></div>`).join('');
 const t=state.table;
 if(state.winner!==null){$('#arena').innerHTML=`<div class="arena-kicker">本局结束</div><div class="arena-empty">${state.winner===0?'你先出完了！':names[state.winner]+'先出完了'}</div><p class="arena-empty-small">${state.turn-1} 个回合 · ${state.history.filter(h=>h.type==='play').length} 次出牌</p><button class="outline-btn" id="again-table" style="color:var(--paper);margin-top:20px">再来一局 ↗</button>`;$('#again-table').onclick=()=>openNew();}
 else if(state.mode==='A'&&t){$('#arena').innerHTML=`<div class="arena-kicker">${names[t.player]}的出牌 · 需要更大的质量值</div><div class="compound-slip"><div class="formula">${f(t.formula)}</div><div class="compound-name">${esc(t.name)}</div><div class="mass">M = ${massText(t.mass)}</div></div><p class="arena-sub">${t.cards.length} 张原子牌${t.category==='有机物'?' · 有机物':''}${state.passes?' · 已有 1 人过牌':''}</p>`;}
 else if(state.mode==='B'){const c=countCards(state.context);$('#arena').innerHTML=`<div class="arena-kicker">待接原子组 C · 全部使用</div><div class="compound-slip"><div class="formula">${f(formulaOf(c))}</div><div class="compound-name">${state.context.length} 个原子，接成一种物质</div><div class="mass">${t?'上一手：'+esc(t.name):'从这里开始'}</div></div><p class="arena-sub">${state.dryTurns?`连续 ${state.dryTurns} / 6 回合摸牌`:'你新出的原子，将留给下一家'}</p>`;}
 else{$('#arena').innerHTML=`<div class="arena-kicker">${names[state.current]}领出 · 不限质量</div><div class="arena-empty">把原子，组成可能。</div><p class="arena-empty-small">选几张牌拼成物质，或先出一张原子。<br>最先出完手牌的人获胜。</p>`;}
 $('#table-foot').innerHTML=`<span>第 ${state.turn} 回合 · 三人桌</span><span>${state.mode==='A'?'相同质量不能压牌':`摸牌堆 ${state.stock.length} 张 · 弃牌 ${state.discard.length} 张`}</span>`;
 $('#hand-count').textContent=String(state.hands[0].length).padStart(2,'0');
 $('#turn-status').textContent=state.winner!==null?'本局已结束，手牌保留供复盘。':state.current===0?(state.mode==='A'?(t?'轮到你了，选择质量更大的组合。':'由你领出，选择任意合法组合。'):'轮到你了，补全桌面的原子组，或摸一张。'):`等待${names[state.current]}出牌，你可以先看看物质图鉴。`;
 const cards=state.hands[0].map((e,i)=>({e,i})).sort((a,b)=>sort==='mass'?ELEMENTS[b.e].mass-ELEMENTS[a.e].mass||a.i-b.i:ELEMENTS[a.e].z-ELEMENTS[b.e].z||a.i-b.i);
 $('#hand').innerHTML=cards.map(({e,i})=>{const el=ELEMENTS[e];return `<button class="atom-card ${selected.has(i)?'selected':''}" data-card="${i}" aria-label="${el.name} ${e}，质量 ${massText(el.mass)}" aria-pressed="${selected.has(i)}" ${state.current!==0||state.winner!==null?'disabled':''} style="--card-bg:${el.bg};--card-ink:${el.ink};--card-accent:${el.accent}" title="${el.name} · ${el.color}"><span class="atomic-number">${el.z}</span>${selected.has(i)?'<span class="check">✓</span>':''}<span class="symbol">${e}</span><span class="element-name">${el.name}</span><span class="atomic-mass">${massText(el.mass)}</span></button>`;}).join('');
 $$('[data-card]').forEach(b=>b.onclick=()=>{const i=+b.dataset.card;selected.has(i)?selected.delete(i):selected.add(i);renderSelection();updateCardSelection();renderSide();});
 renderSelection();renderSide();save();
}
function updateCardSelection(){$$('[data-card]').forEach(b=>{const on=selected.has(+b.dataset.card);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));const old=b.querySelector('.check');if(on&&!old)b.insertAdjacentHTML('afterbegin','<span class="check">✓</span>');if(!on&&old)old.remove();});}
function renderSelection(){const cards=selectedCards(),ownTurn=state.current===0&&state.winner===null,matches=ownTurn?selectedMoves(state,cards):[];
 $('#selection-info').innerHTML=cards.length?`<div class="selection-summary">已选 <strong>${cards.length}</strong> 张 · ${f(formulaOf(countCards(cards)))}</div><div class="selection-note">${matches.length?matches.map(m=>esc(m.name)).slice(0,3).join(' / ')+(matches.length>3?' 等':'')+' · '+massText(matches[0].mass):state.mode==='A'?'M = '+massText(massOf(countCards(cards)))+' · 尚不能出牌':'和 C 合起来还不是可出的物质'}</div>`:'<div class="selection-summary">选牌，组成你的下一手。</div><div class="selection-note">点击卡牌选择，重复点击取消。</div>';
 $('#play-btn').disabled=!ownTurn||!matches.length;$('#play-btn').innerHTML=matches.some(m=>m.graph)?'拼结构 <span>↗</span>':'出牌 <span>↗</span>';
 $('#clear-btn').disabled=!cards.length;$('#hint-btn').disabled=!ownTurn;$('#pass-btn').textContent=state.mode==='A'?'过牌':'摸一张';$('#pass-btn').disabled=!ownTurn||(state.mode==='A'&&!state.table);
}
function renderSide(){
 $$('[data-panel]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===panel)));const box=$('#side-content');
 if(panel==='suggestions'){
  if(state.winner!==null){box.innerHTML='<p class="empty-note">本局已结束。可以在牌局记录中回看，或再开一局。</p>';return;}
  if(state.current!==0){box.innerHTML='<p class="side-help">等对手出牌后，更新你的可出组合。</p><p class="empty-note">先看看图鉴，认识一些新的组合。</p>';return;}
  let moves=legalMoves(state);const chosen=countCards(selectedCards());moves=moves.filter(m=>Object.entries(chosen).every(([e,n])=>(countCards(m.cards)[e]||0)>=n));
  box.innerHTML=`<p class="side-help">${selected.size?'包含已选原子的组合':'按一次可出的牌数排列'} · ${moves.length} 种<br>点击一项，自动帮你选好牌。</p>`+(moves.length?moves.slice(0,70).map(m=>recipeRow(m,true)).join(''):`<p class="empty-note">${selected.size?'当前选择无法组成可出的物质，试着清空后重新选择。':state.mode==='A'?'没有能压过这一手的组合，过牌等待下一轮。':'暂时没有能接上的组合，摸一张试试。'}</p>`);
  $$('[data-recipe]').forEach(b=>b.onclick=()=>stageMove(b.dataset.recipe));
 }else if(panel==='library'){
  const matches=SUBSTANCES.filter(s=>`${s.name} ${s.formula} ${s.category}`.toLowerCase().includes(query.toLowerCase()));
  box.innerHTML=`<input class="search" id="library-search" type="search" placeholder="搜索物质、化学式或类别" aria-label="搜索物质图鉴" value="${esc(query)}"><p class="side-help">已收录 ${SUBSTANCES.length} 种物质 · 找到 ${matches.length} 种</p><div id="library-results">${matches.map(m=>recipeRow(m,false)).join('')||'<p class="empty-note">图鉴暂未收录这个物质。</p>'}</div>`;
  $('#library-search').oninput=e=>{query=e.target.value;const position=e.target.selectionStart;renderSide();const input=$('#library-search');input.focus();try{input.setSelectionRange(position,position);}catch{}};
  $$('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));
 }else{box.innerHTML=`<p class="side-help">最近的出牌在最上方。</p>`+state.history.slice(0,100).map(h=>`<div class="history-entry">${h.type==='play'?`${names[h.player]} <span class="formula">${f(h.formula)}</span><small>${esc(h.name)} · ${h.cards.length} 张 · M ${massText(h.mass)}</small>`:h.type==='draw'?`${names[h.player]}摸了一张牌`:h.type==='pass'?`${names[h.player]}过牌`:h.type==='lead'?`${names[h.player]}重新领出`:h.type==='reset'?`两圈无人出牌，更换 C 为 ${f(h.formula)}`:`${names[h.player]}无牌可摸，跳过`}<small>第 ${h.turn} 回合</small></div>`).join('');if(!state.history.length)box.innerHTML+='<p class="empty-note">牌局刚开始，等待第一手。</p>';}
}
function recipeRow(m,canPlay){return `<button class="recipe" ${canPlay?'data-recipe':'data-detail'}="${m.id}"><span><span class="recipe-formula">${f(m.formula)}</span><span class="recipe-name">${esc(m.name)}</span></span><span class="recipe-tail">${massText(m.mass)}<small>${canPlay?`出 ${m.cards.length} 张${m.graph?' · 拼结构':''}`:m.category}</small></span></button>`;}
function stageMove(id){if(state.current!==0||state.winner!==null)return;const move=legalMoves(state).find(m=>m.id===id);if(!move)return;selected.clear();for(const e of move.cards){const i=state.hands[0].findIndex((v,i)=>v===e&&!selected.has(i));if(i>=0)selected.add(i);}updateCardSelection();renderSelection();renderSide();}
function apply(next){state=next;selected.clear();hintIndex=0;render();if(state.winner!==null){setTimeout(()=>{if(!modal.open)openWinner();},450);}else scheduleBot();}
function scheduleBot(){clearTimeout(timer);const epoch=++botEpoch;if(state.current===0||state.winner!==null||modal.open)return;timer=setTimeout(()=>{if(epoch!==botEpoch||modal.open||state.current===0)return;const move=chooseBotMove(state);apply(move?play(state,move.id,move.cards):skip(state));},1150);}
function submit(){const cards=selectedCards(),matches=selectedMoves(state,cards);if(!matches.length||state.current!==0)return;if(matches.length>1){showModal(`<div class="modal-header"><h2>选择你要组成的物质</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><p class="muted">相同原子可以有不同结构。它们的质量值相同。</p>${matches.map(m=>recipeRow(m,false)).join('')}`);$$('[data-detail]').forEach(b=>b.onclick=()=>beginMove(matches.find(m=>m.id===b.dataset.detail)));}else beginMove(matches[0]);}
function beginMove(move){if(move.graph)openPuzzle(move);else{closeModal();apply(play(state,move.id,selectedCards()));}}
function showModal(html){clearTimeout(timer);botEpoch++;$('#modal-content').innerHTML=`<div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();$$('[data-close]').forEach(b=>b.onclick=closeModal);}
function closeModal(){modal.close();puzzle=null;scheduleBot();}
modal.addEventListener('close',()=>{puzzle=null;scheduleBot();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function openNew(mode=state.mode){let opts={mode,size:state.size,strategy:state.strategy};const draw=()=>{showModal(`<div class="modal-header"><h2>洗牌，重新开始。</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><p class="muted">你与林同学、周同学同桌。${state.winner===null&&state.turn>1?'开始后会结束当前对局。':'选好规则就可以开局。'}</p><h3>这次怎么玩</h3><div class="option-row"><button data-option="mode" data-value="A" class="choice ${opts.mode==='A'?'selected':''}">A · 质量竞技<small>牌越重，压得越大</small></button><button data-option="mode" data-value="B" class="choice ${opts.mode==='B'?'selected':''}">B · 化学接龙<small>补全原子，留给下一家</small></button></div><h3>本局牌数</h3><div class="option-row"><button data-option="size" data-value="72" class="choice ${opts.size===72?'selected':''}">72 张<small>轻量一局</small></button><button data-option="size" data-value="108" class="choice ${opts.size===108?'selected':''}">108 张<small>更多组合空间</small></button></div><h3>怎样抽牌</h3><div class="option-row"><button data-option="strategy" data-value="mixed" class="choice ${opts.strategy==='mixed'?'selected':''}">配方混合<small>约 2/3 配方原子＋随机补足</small></button><button data-option="strategy" data-value="random" class="choice ${opts.strategy==='random'?'selected':''}">自由随机<small>从 1,800 张总牌池抽取</small></button></div><p class="muted">${opts.mode==='A'?'所有牌均分，每人 '+opts.size/3+' 张。允许单原子、单质及图鉴中的物质。':'每人 9 张起手，不限出牌张数。连续两圈摸牌后更换 C。'} 有机物需要完成一次结构拼接。</p><div class="modal-footer"><button class="primary-btn" id="start-game">发牌，开始 ↗</button></div>`);$$('[data-option]').forEach(b=>b.onclick=()=>{opts[b.dataset.option]=b.dataset.option==='size'?+b.dataset.value:b.dataset.value;draw();});$('#start-game').onclick=()=>{state=newGame({...opts,seed:crypto.getRandomValues(new Uint32Array(1))[0]});selected.clear();hintIndex=0;query='';closeModal();render();toast('牌已洗好，由你先手。');};};draw();}
function openRules(){showModal(`<div class="modal-header"><h2>桌边的几条约定</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><h3>A · 质量竞技</h3><ol><li>所有牌均分，轮流出牌。可以出一个原子，也可以组成图鉴中的一种物质。</li><li>跟牌质量值必须严格大于上一手，牌数不限。质量相同不能压。</li><li>其余两人都过牌后，最后出牌的人重新领出，不受上一手质量限制。</li><li>最先出完所有手牌的人获胜。</li></ol><h3>B · 化学接龙</h3><ol><li>每人初始 9 张，桌面随机翻出一个原子作为 C。</li><li>你出的原子 P 与 C 的全部原子，必须恰好组成图鉴中的一种物质。P 不必独立成物质，也不限张数。</li><li>旧 C 进入弃牌堆，新出的 P 成为下一位的 C。也可以摸一张并结束回合。</li><li>三人连续 6 个回合无人出牌，就更换 C；一旦成功出牌，重新计数。摸牌堆空时洗回弃牌。</li><li>最先出完手牌的人获胜。只按原子数量拼合，不保留上一手化学键。</li></ol><h3>什么算合法物质？</h3><p class="muted">当前以图鉴收录的 ${SUBSTANCES.length} 种物质为准，含单质、无机物和有机物。单原子是 A 的独立牌型。不能任意倍写化学式，也不能把几种物质合在一起出。</p><h3>有机物怎样拼结构？</h3><p class="muted">选择物质后，连接带氢的原子基团，选择单、双或三键。氢已标在基团上，不需要逐个连氢。结构允许旋转和等价节点互换；不会要求画成固定方向。</p><h3>颜色与质量值</h3><p class="muted">颜色取自单质常见外观；磷采用红磷配色，碳采用石墨配色。无色气体保留纸白，仅用细线区分。质量统一按卡面数值求和，保留三位小数；同分异构体仍然同质量。</p><p class="muted">这是物质组成游戏，不模拟真实化学反应条件。游戏自动保存在当前浏览器，电脑玩家只根据自己的手牌和桌面行动。</p><div class="modal-footer"><button class="primary-btn" data-close>回到牌桌</button></div>`);}
function openDeck(){const counts=countCards(state.deck);showModal(`<div class="modal-header"><h2>这副牌的来历</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><p class="muted">从 1,800 张、19 种元素的总牌池生成 ${state.size} 张临时牌库。${state.strategy==='mixed'?'先按随机物质配方取牌，再随机补足；所有牌打散后分发。':'完全随机、不放回抽取。'} 配方种子只保证全牌库有组合基础，不保证每位玩家拿到完整配方。</p><table class="rules-table"><thead><tr><th>元素</th><th>数量</th><th>卡面质量值</th><th>单质取色</th></tr></thead><tbody>${Object.keys(counts).sort((a,b)=>ELEMENTS[a].z-ELEMENTS[b].z).map(e=>`<tr><td>${e} · ${ELEMENTS[e].name}</td><td>${counts[e]}</td><td>${massText(ELEMENTS[e].mass)}</td><td>${ELEMENTS[e].color}</td></tr>`).join('')}</tbody></table>${state.seeds.length?'<h3>本局的配方种子</h3><p>'+state.seeds.map(id=>`<span class="pill">${esc(SUBSTANCES.find(s=>s.id===id).name)}</span>`).join('')+'</p>':''}<p class="muted" style="margin-top:14px">牌局编号 ${state.seed} · 卡片取自固定总牌池，配比仍可继续根据试玩调优。</p>`);}
function openDetail(id){const s=SUBSTANCES.find(s=>s.id===id);if(!s)return;const move=state.current===0?legalMoves(state).find(m=>m.id===id):null;showModal(`<div class="modal-header"><h2>${esc(s.name)}</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><div class="reference" style="font:36px Georgia">${f(s.formula)}</div><p>${s.category} · ${s.size} 个原子 · M = ${massText(s.mass)}</p><p>${Object.entries(s.counts).map(([e,n])=>`<span class="pill">${ELEMENTS[e].name} ${e} × ${n}</span>`).join('')}</p>${s.graph?`<h3>结构参考</h3>${graphSvg(s.graph,s.graph.bonds,false)}<p class="muted">${esc(s.graph.reference)}</p><p class="muted">图中氢合并标在相连的原子基团上。</p>`:'<p class="muted">按照上方化学式的原子数量出牌，不把化学式任意倍写。</p>'}<div class="modal-footer">${move?'<button id="detail-stage" class="primary-btn">选出这些牌</button>':'<button class="outline-btn" data-close>回到牌桌</button>'}</div>`);if(move)$('#detail-stage').onclick=()=>{closeModal();stageMove(id);};}
function positions(n){if(n===1)return[{x:280,y:140}];if(n===2)return[{x:190,y:140},{x:370,y:140}];return Array.from({length:n},(_,i)=>({x:280+220*Math.cos(-Math.PI/2+i*Math.PI*2/n),y:140+100*Math.sin(-Math.PI/2+i*Math.PI*2/n)}));}
function graphSvg(graph,bonds,interactive,coords=positions(graph.nodes.length),active=-1){const radius=graph.nodes.length>10?21:26;const lines=bonds.map(([a,b,o])=>{const A=coords[a],B=coords[b],dx=B.x-A.x,dy=B.y-A.y,len=Math.hypot(dx,dy),nx=-dy/len,ny=dx/len;return Array.from({length:o},(_,i)=>{const off=(i-(o-1)/2)*6;return `<line class="bond" x1="${A.x+dx/len*radius+nx*off}" y1="${A.y+dy/len*radius+ny*off}" x2="${B.x-dx/len*radius+nx*off}" y2="${B.y-dy/len*radius+ny*off}"/>`;}).join('');}).join('');return `<svg class="structure-board" viewBox="0 0 560 280" role="${interactive?'group':'img'}" aria-label="${interactive?'选择两个原子基团连接化学键':'有机物结构示意'}">${lines}${graph.nodes.map((node,i)=>`<g class="structure-node ${i===active?'selected':''}" ${interactive?`data-node="${i}" role="button" tabindex="0" aria-label="第 ${i+1} 个基团 ${node.label}"`:''} transform="translate(${coords[i].x},${coords[i].y})"><circle r="${radius}"/><text text-anchor="middle" dominant-baseline="central">${esc(node.label)}</text></g>`).join('')}</svg>`;}
function openPuzzle(move){const coords=shuffle(positions(move.graph.nodes.length));puzzle={move,bonds:[],order:1,active:-1,coords,reference:false};showModal(`<div class="modal-header"><h2>把${esc(move.name)}拼出来</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><p class="muted">${f(move.formula)} · 点击两个基团连接化学键。相同键再连一次即可删除；氢已经包含在基团里。</p><div class="bond-toolbar"><span>键型</span><button class="bond-tool selected" data-order="1">— 单键</button><button class="bond-tool" data-order="2">＝ 双键</button><button class="bond-tool" data-order="3">≡ 三键</button><button class="text-btn" id="undo-bond">撤销</button><button class="text-btn" id="structure-help">查看参考</button></div><div id="puzzle-board"></div><div id="puzzle-reference"></div><p class="structure-status" id="structure-status">${move.graph.nodes.length===1?'这个分子只有一个中心原子，氢已齐全，可以直接确认。':'从一个基团开始，接到另一个基团。'}</p><div class="modal-footer"><button class="outline-btn" data-close>返回选牌</button><button class="primary-btn" id="confirm-structure">确认结构并出牌 ↗</button></div>`);
 $$('[data-order]').forEach(b=>b.onclick=()=>{puzzle.order=+b.dataset.order;$$('[data-order]').forEach(x=>x.classList.toggle('selected',x===b));});
 $('#undo-bond').onclick=()=>{puzzle.bonds.pop();puzzle.active=-1;renderPuzzle();};$('#structure-help').onclick=()=>{puzzle.reference=!puzzle.reference;$('#puzzle-reference').innerHTML=puzzle.reference?`<p class="reference">${esc(move.graph.reference)}</p>${graphSvg(move.graph,move.graph.bonds,false)}`:'';};
 $('#confirm-structure').onclick=()=>{if(!graphMatches(move.graph,puzzle.bonds)){$('#structure-status').textContent='结构还没有连接正确。检查每个基团的邻居和键型，或展开参考。';toast('再检查一下连接关系。');return;}const cards=selectedCards();closeModal();apply(play(state,move.id,cards));toast('结构正确，出牌成功。');};renderPuzzle();
}
function renderPuzzle(){if(!puzzle)return;$('#puzzle-board').innerHTML=graphSvg(puzzle.move.graph,puzzle.bonds,true,puzzle.coords,puzzle.active);$$('[data-node]').forEach(b=>{const action=()=>{const n=+b.dataset.node;if(puzzle.active<0)puzzle.active=n;else if(puzzle.active===n)puzzle.active=-1;else{const a=puzzle.active,index=puzzle.bonds.findIndex(([x,y])=>x===a&&y===n||x===n&&y===a);if(index>=0){if(puzzle.bonds[index][2]===puzzle.order)puzzle.bonds.splice(index,1);else puzzle.bonds[index][2]=puzzle.order;}else puzzle.bonds.push([a,n,puzzle.order]);puzzle.active=-1;}renderPuzzle();};b.onclick=action;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action();}};});}
function openWinner(){showModal(`<div class="modal-header"><h2>这一局，记下来。</h2><button class="close-btn" data-close aria-label="关闭">×</button></div><p class="winner-name">${state.winner===0?'你赢了。':names[state.winner]+'获胜。'}</p><p class="muted">${state.mode==='A'?'质量竞技':'化学接龙'} · ${state.size} 张牌 · ${state.turn-1} 个回合</p><table class="rules-table"><tbody>${names.map((n,i)=>`<tr><td>${n}</td><td>${i===state.winner?'已出完':`剩余 ${state.hands[i].length} 张`}</td></tr>`).join('')}</tbody></table><div class="modal-footer"><button class="outline-btn" id="review-game">回看牌局</button><button class="primary-btn" id="again-modal">再来一局 ↗</button></div>`);$('#review-game').onclick=()=>{panel='history';closeModal();renderSide();};$('#again-modal').onclick=()=>openNew();}
$('#clear-btn').onclick=()=>{selected.clear();updateCardSelection();renderSelection();renderSide();};$('#hint-btn').onclick=()=>{const moves=legalMoves(state);if(!moves.length){toast(state.mode==='A'?'没有更大的组合，先过牌。':'暂时接不上，摸一张试试。');return;}const move=moves[hintIndex++%moves.length];stageMove(move.id);toast(`${move.name} · 可出 ${move.cards.length} 张`);};$('#play-btn').onclick=submit;$('#pass-btn').onclick=()=>{if(state.current===0&&state.winner===null)apply(skip(state));};$('#sort').onchange=e=>{sort=e.target.value;render();};$('#new-btn').onclick=()=>openNew();$('#rules-btn').onclick=openRules;$('#deck-info').onclick=openDeck;$$('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==state.mode)openNew(b.dataset.mode);});$$('[data-panel]').forEach(b=>b.onclick=()=>{panel=b.dataset.panel;renderSide();});
document.addEventListener('keydown',e=>{if(modal.open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='Escape'){selected.clear();updateCardSelection();renderSelection();renderSide();}if(e.key==='Enter'&&!$('#play-btn').disabled&&document.activeElement===document.body)submit();});
// Optional WebMCP interface: only visible player information is exposed.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_chemical_card_table',title:'查看化学牌桌',description:'Read the current visible table, your hand, and legal moves; opponents remain hidden.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('此操作不接受参数');return{mode:state.mode,current:state.current,winner:state.winner,context:state.context,table:state.table,hand:state.hands[0],opponentCounts:state.hands.slice(1).map(h=>h.length),moves:state.current===0?legalMoves(state).map(m=>({id:m.id,name:m.name,cards:m.cards})):[]};}},{name:'stage_chemical_card_move',title:'选择出牌组合',description:'Select a currently legal move in the visible hand. Does not play the cards; organic structures still require confirmation.',inputSchema:{type:'object',properties:{moveId:{type:'string'}},required:['moveId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='moveId')||typeof input.moveId!=='string'||state.current!==0||modal.open||!legalMoves(state).some(m=>m.id===input.moveId))throw Error('当前无法选择此组合');stageMove(input.moveId);return{selected:selectedCards(),played:false};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();scheduleBot();
